const body = $json.body ?? $json;

const projectId = body.project_id;
const activityId = body.activity_id;
const imageType = body.image_type;
const imageUrl = body.image_url;

if (!projectId || typeof projectId !== 'string') {
  throw new Error("Validation Error: project_id is required.");
}

if (!activityId || typeof activityId !== 'string') {
  throw new Error("Validation Error: activity_id is required.");
}

if (!imageType || typeof imageType !== 'string') {
  throw new Error("Validation Error: image_type is required.");
}

const allowedImageTypes = [
  "DESIGN",
  "SITE"
];

const normalizedImageType = imageType.trim().toUpperCase();

if (!allowedImageTypes.includes(normalizedImageType)) {
  throw new Error(
    `Validation Error: image_type must be DESIGN or SITE. Received: ${imageType}`
  );
}

if (!imageUrl || typeof imageUrl !== 'string') {
  throw new Error("Validation Error: image_url is required.");
}

return {
  json: {
    project_id: projectId.trim(),
    activity_id: activityId.trim(),
    image_type: normalizedImageType,
    image_url: imageUrl.trim(),
    received_at: new Date().toISOString()
  }
};

const imageUrl = $json.image_url;

if (!imageUrl) {
  throw new Error("Vision Error: image_url is missing.");
}

const imageType = $json.image_type;

const prompt = `
You are the Visual Execution Verification AI for an infrastructure project.

Analyze the provided ${imageType} image.

Return ONLY valid JSON.

Required fields:

{
  "view_type": "FRONT | LEFT | RIGHT | TOP | OTHER",
  "view_confidence": 0.0,
  "visible_asset": null,
  "discipline": null,
  "location": null,
  "image_quality": "GOOD | FAIR | POOR",
  "confidence": 0.0,
  "evidence": []
}

Rules:
- Do not invent information that is not visually supported.
- view_confidence must be between 0 and 1.
- confidence must be between 0 and 1.
- visible_asset should be null if the asset cannot be identified.
- discipline should be null if it cannot be visually determined.
- location should be null if it cannot be determined from the image.
- evidence must contain short observations directly supported by the image.
- Do not estimate construction completion percentage.
`;

return {
  json: {
    ...$json,
    vision_prompt: prompt
  }
};

const output = $json;

let result = output;

// Gemini response structure:
// content.parts[0].text
if (
  output.content &&
  Array.isArray(output.content.parts) &&
  output.content.parts[0] &&
  typeof output.content.parts[0].text === 'string'
) {
  result = output.content.parts[0].text;
}

// If result is a string, remove markdown code fences and parse JSON
if (typeof result === 'string') {
  result = result
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    result = JSON.parse(result);
  } catch (e) {
    throw new Error(
      'Gemini returned invalid JSON: ' + result
    );
  }
}

return {
  json: {
    project_id: $('Validate Visual Input').item.json.project_id,
    activity_id: $('Validate Visual Input').item.json.activity_id,
    image_type: $('Validate Visual Input').item.json.image_type,

    view_type: result.view_type ?? 'OTHER',
    view_confidence: Number(result.view_confidence ?? 0),

    visible_asset: result.visible_asset ?? null,
    discipline: result.discipline ?? null,
    location: result.location ?? null,

    image_quality: result.image_quality ?? 'POOR',
    confidence: Number(result.confidence ?? 0),

    evidence: Array.isArray(result.evidence)
      ? result.evidence
      : []
  }
};

const data = $json;

// Required fields
if (!data.project_id) {
  throw new Error("Validation Error: project_id is missing.");
}

if (!data.activity_id) {
  throw new Error("Validation Error: activity_id is missing.");
}

if (!["DESIGN", "SITE"].includes(data.image_type)) {
  throw new Error(
    `Validation Error: invalid image_type: ${data.image_type}`
  );
}

// Numeric confidence validation
const viewConfidence = Number(data.view_confidence);
const confidence = Number(data.confidence);

if (
  !Number.isFinite(viewConfidence) ||
  viewConfidence < 0 ||
  viewConfidence > 1
) {
  throw new Error(
    "Validation Error: view_confidence must be between 0 and 1."
  );
}

if (
  !Number.isFinite(confidence) ||
  confidence < 0 ||
  confidence > 1
) {
  throw new Error(
    "Validation Error: confidence must be between 0 and 1."
  );
}

// Allowed values
const allowedViews = [
  "FRONT",
  "LEFT",
  "RIGHT",
  "TOP",
  "OTHER"
];

if (!allowedViews.includes(data.view_type)) {
  throw new Error(
    `Validation Error: invalid view_type: ${data.view_type}`
  );
}

const allowedQuality = [
  "GOOD",
  "FAIR",
  "POOR"
];

if (!allowedQuality.includes(data.image_quality)) {
  throw new Error(
    `Validation Error: invalid image_quality: ${data.image_quality}`
  );
}

// Evidence must be an array
if (!Array.isArray(data.evidence)) {
  throw new Error(
    "Validation Error: evidence must be an array."
  );
}

return {
  json: {
    ...data,
    validation_status: "VALID",
    validated_at: new Date().toISOString()
  }
};

const data = $json;

return {
  json: {
    project_id: data.project_id,
    activity_id: data.activity_id,
    image_type: data.image_type,

    view_type: data.view_type,
    view_confidence: data.view_confidence,

    visible_asset: data.visible_asset,
    discipline: data.discipline,
    location: data.location,

    image_quality: data.image_quality,
    confidence: data.confidence,
    evidence: data.evidence,

    validation_status: data.validation_status,

    analysis_status: "COMPLETED",

    analyzed_at: new Date().toISOString()
  }
};

