parameters.jsCode:
const imageUrl = $json.image_url;

if (!imageUrl) {
  throw new Error("Image Processing Error: image_url is missing.");
}

return {
  json: {
    ...$json,

    image_processing: {
      required: true,
      max_dimension: 1600,
      target_format: "JPEG",
      quality: 80,
      optimization_status: "PENDING"
    }
  }
};

const data = $json;

const confidence = Number(data.confidence ?? 0);
const viewConfidence = Number(data.view_confidence ?? 0);
const imageQuality = data.image_quality;

let reviewStatus = "AUTO_REVIEWABLE";
let reviewReason = null;

// Poor image quality
if (imageQuality === "POOR") {
  reviewStatus = "REVIEW_REQUIRED";
  reviewReason = "Image quality is too poor for reliable visual verification.";
}

// Low overall confidence
else if (confidence < 0.60) {
  reviewStatus = "REVIEW_REQUIRED";
  reviewReason = "AI confidence is below the reliable verification threshold.";
}

// Low view confidence
else if (viewConfidence < 0.60) {
  reviewStatus = "REVIEW_REQUIRED";
  reviewReason = "View classification confidence is too low.";
}

// Missing visible asset
else if (!data.visible_asset) {
  reviewStatus = "REVIEW_REQUIRED";
  reviewReason = "No reliable visible asset could be identified.";
}

return {
  json: {
    ...data,
    review_status: reviewStatus,
    review_reason: reviewReason,
    review_decided_at: new Date().toISOString()
  }
};

const input = $json;

let errorMessage = "Visual AI analysis failed.";

if (input.error) {
  if (typeof input.error === "string") {
    errorMessage = input.error;
  } else if (input.error.message) {
    errorMessage = input.error.message;
  }
}

return {
  json: {
    success: false,

    project_id: input.project_id ?? null,
    activity_id: input.activity_id ?? null,
    image_type: input.image_type ?? null,

    analysis_status: "FAILED",
    review_status: "REVIEW_REQUIRED",

    error_message: errorMessage,

    retry_allowed: true,

    failed_at: new Date().toISOString()
  }
};

